real_t algorithm_reduce_sum(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t acc = 0.0;
    const Index_type LEN = LEN_1D;
    const real_t *x = &x[0];

    for (int nl = 0; nl < iterations; nl++) {
        real_t s = 0.0;
        Index_type i = 0;

        while (i < LEN) {
            size_t vl = __riscv_vsetvl_e64m1((size_t)(LEN - i));
            vfloat64m1_t vx = __riscv_vle64_v_f64m1((const double *)(x + i), vl);
            vfloat64m1_t vs = __riscv_vfmv_v_f_f64m1(0.0, vl);
            vs = __riscv_vfadd_vv_f64m1(vs, vx, vl);
            s += __riscv_vfmv_f_s_f64m1_f64(__riscv_vfredusum_vs_f64m1_f64m1(vs, __riscv_vfmv_v_f_f64m1(0.0, vl), vl));
            i += (Index_type)vl;
        }

        acc += s;
        dummy(x, NULL, NULL, NULL, NULL, s);
    }

    y[0] = acc / (real_t)(iterations * LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

