    gettimeofday(&func_args->t1, NULL);

    real_t cls = 1.0f, p_cut = 1.0e-7f, pmin = 0.0f, eosvmax = 1.0e9f;

    const Index_type n = APPS_N1D;
    const real_t one = 1.0f;

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        Index_type i = 0;
        for (; i < n; ++i) {
            apps_bvc[i] = cls * (apps_compression[i] + one);
        }

        i = 0;
        for (; i < n; ++i) {
